"""AQS-OPS-002 maintenance plan (X-OPS-02, A-M-189): inspection and replacement intervals per unit, from the unit's attributes on the graph.
Pressurised (relief case with P1): API510_2022 external 5 y, internal min(half remaining life, 10 y); relief device API576_2017 at 5 y (2 y in
fouling/corrosive or oxygen service). Atmospheric vessels and tanks: annual external visual, 10 y internal (A-M-189). Piping: API570_2016
class by fluid. Powered units: rotating rule (maint_rotating). Electrical: NFPA70B_2023 annual thermography, 36-month service. Standby power:
NFPA110_2022 weekly inspection, monthly load run. Fire water: NFPA25_2023. Inserts: maint_insert_life_y. Also writes models/units/<U>/maint.csv.
Run: python3 docs-authority/_maint.py"""
import csv, json, os, sys
R = os.path.dirname(os.path.dirname(os.path.abspath(__file__))); os.chdir(R); sys.path.insert(0, R)
from flow_graph.param import drivers as DR
from flow_graph.param.refs import cite
for k in ('API510_2022', 'API570_2016', 'API576_2017', 'NFPA25_2023', 'NFPA70B_2023', 'NFPA110_2022', 'NFPA111_2022'): cite(k)
d = DR.load(); life = DR.val(d, 'maint_insert_life_y'); rot = DR.val(d, 'maint_rotating')
g = json.load(open('flow_graph/plant_flow_graph.json'))
ELEC = {'rectifier', 'inverter', 'pv', 'flow_battery', 'pem_fc', 'iem_fc', 'pem_electrolyser', 'genset', 'hydro'}
CORR = ('HCl', 'HNO3', 'Br', 'NaOH', 'acid', 'chlor')
CHEM = {'HTC', 'YEAST', 'ABE', 'ACETOX', 'ALD', 'GLYOXAL', 'FORM', 'MEAM', 'IMID', 'QUAT', 'ACEX', 'HNO3', 'BUCL', 'ETOH_STILL', 'BUOH_STILL', 'STRUVITE', 'ASH', 'IODIDE', 'DIGESTER', 'CLARIFIER'}   # process units under the farm class
rows = []; tot = 0
for n in g['nodes']:
    u = n['unit_id']; p = n.get('params') or {}; c = n.get('class') or ''; c = 'vessel' if u in CHEM else c; rb = p.get('relief_basis') or {}; t = []
    if not p or p.get('presence') == 'absent' or c in ('boundary', 'building'): continue
    if 'P1_kPa_abs' in rb:
        foul = u == 'CRYO_O2' or any(x in rb.get('case', '') for x in CORR)
        t += [('external inspection', 'API 510 6.4', 5), ('internal or on-stream thickness', 'API 510 6.5', 10), ('relief valve bench test', 'API 576', 2 if foul else 5)]
    elif p.get('design_kPa') is not None and c not in ELEC and c not in ('header', 'recycle_pipe', 'farm', 'hab', 'shop', 'dock'):
        t += [('external visual', 'A-M-189', 1), ('internal inspection', 'A-M-189', 10)]
    if c in ('header', 'recycle_pipe'): t += [('thickness survey', 'API 570 class 2', 10), ('external visual', 'API 570', 5)]
    kw = (n.get('continuous_kw') or {}).get('value') or 0
    if kw > 0 and c not in ELEC and c not in ('farm', 'hab', 'shop', 'dock', 'heat_battery', 'digest'):
        t += [('lubrication', 'A-M-189', rot['lube_mo']/12), ('vibration and temperature check', 'A-M-189', rot['vibration_mo']/12), ('bearing replacement', 'A-M-189', rot['bearing_y']), ('seal replacement', 'A-M-189', rot['seal_y'])]
    if c in ELEC: t += [('infrared thermography', 'NFPA 70B', 1), ('electrical service (torque, insulation resistance)', 'NFPA 70B', 3)]
    if c == 'genset': t += [('inspection', 'NFPA 110 8.4.1', 1/52), ('load run 30 min', 'NFPA 110 8.4.2', 1/12)]
    if c == 'hydro': t += [('turbine-generator load run', 'NFPA 111 8.4', 1/12), ('reservoir cell drain-down inspection (one cell at a time)', 'A-M-189', 5)]
    if c == 'farm': t += [('bed and nutrient line clean-down', 'A-M-189', 0.25)]
    if u in life: t += [('replace process insert', 'A-M-189 maint_insert_life_y', life[u])]
    if not t: t = [('external visual', 'A-M-189', 1)]
    os.makedirs(f'models/units/{u}', exist_ok=True)
    with open(f'models/units/{u}/maint.csv', 'w', newline='') as f:
        w = csv.writer(f); w.writerow(['task', 'basis', 'interval_y']); w.writerows([(a, b, round(y, 4)) for a, b, y in t])
    rows.append((u, c, t)); tot += len(t)
fmt = lambda y: f'{y*52:.0f} wk' if y < 1/12 + 1e-9 and y < 0.08 else (f'{y*12:.0f} mo' if y < 1 else f'{y:g} y')
md = ['# Maintenance plan', '', 'Document number: AQS-OPS-002', 'Revision: A', 'Date: 2026-10-16', 'Authority: AQS-PLAN-007 X-OPS-02. Generated by `docs-authority/_maint.py`; per-unit tables in `models/units/<UNIT>/maint.csv`. Study. A-M-189.', '',
      'Gas detectors (AQS-SAF-006): quarterly bump test, 6-monthly calibration, heads replaced at 3 years (electrochemical) or 5 years (catalytic/IR) (A-M-198). Safety instrumented functions (AQS-CTL-003): proof test yearly. Fire protection (AQS-SAF-005) per NFPA 25: weekly fire pump churn test, quarterly valve and alarm tests, annual sprinkler inspection, 5-year internal inspection of the fire reserve cells and piping.', '',
      '| Unit | Class | Tasks (interval) |', '|---|---|---|']
md += [f"| {u} | {c} | " + '; '.join(f'{a} ({fmt(y)}, {b})' for a, b, y in t) + ' |' for u, c, t in rows]
md += ['', f'{len(rows)} units, {tot} tasks. Intervals marked A-M-189 are study values until the first year of condition data; code intervals are maxima.']
open('docs-authority/MAINT_PLAN.md', 'w').write('\n'.join(md) + '\n'); print(len(rows), tot)
